using System.Diagnostics;
namespace CombatSolver;
internal static class TaskRecoveryMeasurement
{
    private static readonly long[] Counts = new long[3], Ticks = new long[3], Unknown = new long[3], Prunes = new long[3];
    internal static void RecordQuery(int category, int value, long ticks)
    {
        Interlocked.Increment(ref Counts[category]);
        Interlocked.Add(ref Ticks[category], ticks);
        if (value == int.MaxValue) Interlocked.Increment(ref Unknown[category]);
    }
    internal static void RecordPrunes(int category, int count) => Interlocked.Add(ref Prunes[category], count);
    internal static void Dump(SearchDiagnosticsSink diagnostics)
    {
        for (int category = 0; category < 3; category++)
            diagnostics.Info($"[CombatSolver/Test] RECOVERY_QUERY_MEASUREMENT category={category} " +
                $"count={Interlocked.Read(ref Counts[category])} unknown_or_unavailable={Interlocked.Read(ref Unknown[category])} " +
                $"elapsed_ms={1000d * Interlocked.Read(ref Ticks[category]) / Stopwatch.Frequency:F4} " +
                $"request_prunes={Interlocked.Read(ref Prunes[category])}");
    }
}
